(function () {
  var map = {
    archive: function () { return ARCHIVE_ICON; },
    reply:   function () { return REPLY_ICON; },
    back:    function () { return ARROW_ICON; },
    fwd:     function () { return ARROW_ICON.replace('class="arrow-icon"', 'class="arrow-icon fwd"'); }
  };
  document.querySelectorAll("[data-icon]").forEach(function (el) {
    var f = map[el.getAttribute("data-icon")];
    if (f && !el.querySelector("svg")) el.innerHTML = f();
  });
})();
